queries.cql:
// CrowdStrike CQL for Mule Rapid ATM Withdrawal After Inbound Transfer
// Repository: flame-banking-transaction-monitoring
// Correlates inbound wire/ACH with rapid ATM cash-out within 4h
((event_type="WIRE_CREDIT" OR event_type="ACH_CREDIT") AND transaction_amount>=2000)
OR (event_type="ATM_WITHDRAWAL" AND transaction_amount>=500)
| selfJoinFilter(account_id, where=[
    {event_type="WIRE_CREDIT" OR event_type="ACH_CREDIT"}
    {event_type="ATM_WITHDRAWAL"}
  ])
| groupBy(account_id, function=[
    count(as=event_count),
    collect([event_type, transaction_amount, @timestamp])
  ], span=4h)
| event_count >= 2
